changeSet.sql:
ALTER TABLE workspace ADD COLUMN authority_generation bigint DEFAULT 0 NOT NULL,
    ADD CONSTRAINT ck_workspace_authority_generation CHECK (authority_generation >= 0);
CREATE FUNCTION membership_narrows_authority() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE'
       OR ROW(NEW.workspace_id, NEW.account_id) IS DISTINCT FROM ROW(OLD.workspace_id, OLD.account_id)
       OR (OLD.left_at IS NULL AND NEW.left_at IS NOT NULL)
       OR array_position(ARRAY['OWNER', 'ADMIN', 'MEMBER'], NEW.role::text)
          > array_position(ARRAY['OWNER', 'ADMIN', 'MEMBER'], OLD.role::text) THEN
        UPDATE public.workspace SET authority_generation = authority_generation + 1 WHERE id = OLD.workspace_id;
    END IF;
    RETURN NULL;
END $$;
CREATE TRIGGER membership_narrows_authority AFTER DELETE OR UPDATE OF workspace_id, account_id, role, left_at ON membership
    FOR EACH ROW EXECUTE FUNCTION membership_narrows_authority();

rollback.sql:
DROP TRIGGER membership_narrows_authority ON membership;
DROP FUNCTION membership_narrows_authority();
ALTER TABLE workspace DROP COLUMN authority_generation;

changeSet.sql:
ALTER TABLE agent_run ADD COLUMN authorization_stamp jsonb DEFAULT jsonb_build_object('workspace', 0) NOT NULL,
    ADD CONSTRAINT ck_agent_run_authorization_stamp CHECK ((jsonb_typeof(authorization_stamp) = 'object'
        AND jsonb_typeof(authorization_stamp -> 'workspace') = 'number'
        AND (authorization_stamp ->> 'workspace') ~ '^[0-9]{1,19}$'
        AND (authorization_stamp ->> 'workspace')::numeric <= 9223372036854775807) IS TRUE) NOT VALID;
CREATE FUNCTION guard_authorization_stamp() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.authorization_stamp IS DISTINCT FROM OLD.authorization_stamp THEN
        RAISE EXCEPTION 'work keeps the authorization stamp it was requested under' USING ERRCODE = '55000';
    END IF;
    RETURN NULL;
END $$;
CREATE TRIGGER agent_run_authorization_stamp_fixed AFTER UPDATE OF authorization_stamp ON agent_run
    FOR EACH ROW EXECUTE FUNCTION guard_authorization_stamp();
ALTER TABLE agent_run DROP CONSTRAINT ck_agent_run_stop_reason;
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_stop_reason CHECK (stop_reason IS NULL
    OR stop_reason IN ('COMPLETED','HANDED_OFF','FAILED','CANCELLED','ATTEMPTS_EXHAUSTED','NOT_STARTED','DEADLINE',
                       'AUTHORITY_CHANGED')) NOT VALID;

rollback.sql:
ALTER TABLE agent_run DROP CONSTRAINT ck_agent_run_stop_reason;
ALTER TABLE agent_run ADD CONSTRAINT ck_agent_run_stop_reason CHECK (stop_reason IS NULL
    OR stop_reason IN ('COMPLETED','HANDED_OFF','FAILED','CANCELLED','ATTEMPTS_EXHAUSTED','NOT_STARTED','DEADLINE'));
DROP TRIGGER agent_run_authorization_stamp_fixed ON agent_run;
DROP FUNCTION guard_authorization_stamp();
ALTER TABLE agent_run DROP COLUMN authorization_stamp;

DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM public.agent_run WHERE stop_reason = 'AUTHORITY_CHANGED')
    OR EXISTS (SELECT 1 FROM public.review WHERE stop_reason = 'AUTHORITY_CHANGED') THEN
  RAISE EXCEPTION 'Restore the verified pre-upgrade backup: runs or reviews record that their access changed';
 END IF;
END $$;
